int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    constexpr int MOD = 1000000007;
    vector<int> previous(n + 2), current(n + 2);
    previous[0] = 1;

    for (int i = 1; i <= n; ++i) {
        current[0] = previous[i - 1];
        for (int j = 1; j <= i; ++j) {
            current[j] = (current[j - 1] + previous[j - 1]) % MOD;
        }
        swap(previous, current);
    }

    int valueN = previous[0];
    int i = n + 1;
    current[0] = previous[i - 1];
    for (int j = 1; j <= i; ++j) {
        current[j] = (current[j - 1] + previous[j - 1]) % MOD;
    }

    cout << (current[0] - valueN + MOD) % MOD;
    return 0;
}

