int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    constexpr int MOD = 1000000007;
    vector<int> previous(n + 2), current(n + 2);
    previous[0] = 1;

    int fn = (n == 0 ? 1 : 0);

    for (int i = 1; i <= n + 1; ++i) {
        current[0] = previous[i - 1];
        for (int j = 1; j <= i; ++j) {
            current[j] = (current[j - 1] + previous[j - 1]) % MOD;
        }
        if (i == n) fn = current[0];
        swap(previous, current);
    }

    cout << (previous[0] - fn + MOD) % MOD;
    return 0;
}

