int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    constexpr int MOD = 1000000007;
    vector<int> prev(n + 2), curr(n + 2);
    prev[0] = 1;

    int fn0 = (n == 0 ? 1 : 0);
    int fn1_0 = 0;

    for (int i = 1; i <= n + 1; ++i) {
        curr[0] = prev[i - 1];
        for (int j = 1; j <= i; ++j) {
            curr[j] = (curr[j - 1] + prev[j - 1]) % MOD;
        }

        if (i == n) fn0 = curr[0];
        if (i == n + 1) fn1_0 = curr[0];

        swap(prev, curr);
        fill(curr.begin(), curr.end(), 0);
    }

    cout << (fn1_0 - fn0 + MOD) % MOD;
    return 0;
}

